// WF-01 · Normalización al contrato interno de BlinkSec.
//
// Punto de desacople del sistema: a partir de aquí nada sabe de qué
// plataforma vino la alerta. Añadir un cuarto SIEM se resuelve escribiendo un
// normalizador en lib/normalize.js, sin tocar nada aguas abajo.

// @blinksec-inject: lib/normalize.js

const entrada = $input.first().json;

let alertas;
try {
  alertas = normalize(entrada.source, entrada.rawBody);
} catch (e) {
  // Un payload irrecuperable no se procesa a medias: se deriva a WF-99 con el
  // contexto suficiente para que alguien arregle la regla de origen.
  throw new Error(`Normalización fallida (${entrada.source}): ${e.message}`);
}

// Elastic puede traer varias alertas en un solo POST. Cada una recibe su
// propio alert_id derivado, para que la idempotencia funcione por alerta y no
// por lote: si el lote se reenvía con una alerta nueva, sólo esa se procesa.
return alertas.map((a, i) => ({
  json: {
    ...a,
    alert_id: alertas.length === 1 ? entrada.alertId : `${entrada.alertId}-${i}`,
    agent_id: entrada.agentId,
    ingestStartedAt: entrada.ingestStartedAt,
  },
}));

// WF-01 · Fusión del inventario de activos.
//
// asset.criticality es el dato que decide si una contención se ejecuta sola o
// pasa por un humano. Sin él, el sistema no distingue aislar un portátil de
// aislar la base de datos de producción.

const alerta = $('Normalizar').first().json;
const filas = $input.all().map((i) => i.json).filter((f) => f && f.hostname);
const activo = filas[0];

if (!activo) {
  // Activo desconocido: se mantiene el 'high' conservador y se deja
  // constancia. Un inventario incompleto es un hallazgo operativo, no una
  // excusa para automatizar a ciegas.
  return [
    {
      json: {
        ...alerta,
        asset: { ...alerta.asset, criticality: 'high', never_isolate: false, inventoryHit: false },
      },
    },
  ];
}

return [
  {
    json: {
      ...alerta,
      asset: {
        ...alerta.asset,
        criticality: activo.criticality,
        never_isolate: activo.never_isolate === true,
        owner_team: activo.owner_team ?? null,
        inventoryHit: true,
      },
    },
  },
];

// WF-01 · Restauración del payload tras la escritura.
//
// El nodo Postgres anterior sustituye el item por el resultado de su consulta
// (aquí: alert_id y es_nueva). Sin restaurar, WF-02 recibiría esa fila en vez
// de la alerta normalizada y planificaría cero consultas de inteligencia —
// sin que nada falle visiblemente.
//
// De paso se aprovecha `es_nueva` del RETURNING: si el UPSERT actualizó en
// lugar de insertar, esta alerta ya se procesó antes y es un reenvío.

const alerta = $('Fusionar criticidad').first().json;
const fila = $input.first().json;

return [
  {
    json: {
      ...alerta,
      esReenvio: fila.es_nueva === false,
    },
  },
];
